      "path": "package.json",
      "content": "{\n  \"name\": \"@anonyjcy/dsh-j-space\",\n  \"version\": \"1.2.4\",\n  \"description\": \"J-Space Cognition Suite SV1 native Agent Preset and standalone plugin for DeepSeek Harness\",\n  \"author\": \"anonyjcy\",\n  \"license\": \"(MIT AND Apache-2.0)\",\n  \"type\": \"module\",\n  \"main\": \"src/index.ts\",\n  \"types\": \"src/index.ts\",\n  \"bin\": {\n    \"dsh-j-space\": \"bin/cli.js\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AnonyJcy/dsh-j-space.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/AnonyJcy/dsh-j-space/issues\"\n  },\n  \"homepage\": \"https://github.com/AnonyJcy/dsh-j-space#readme\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./src/index.ts\",\n      \"default\": \"./src/index.ts\"\n    },\n    \"./installer\": {\n      \"types\": \"./src/installer.ts\",\n      \"default\": \"./src/installer.ts\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"src\",\n    \"bin\",\n    \"preset\",\n    \"vendor/j-space\",\n    \"tools/upstream_integrity.py\",\n    \"NOTICE.md\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"j-space\",\n    \"agent\",\n    \"preset\",\n    \"cognition\",\n    \"reasoning\",\n    \"cordis-plugin\"\n  ],\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.2 <5 || ~4.0.5-alpha.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5-alpha.2\",\n    \"@types/node\": \"^22.20.5\",\n    \"typescript\": \"^5.8.0\",\n    \"vitest\": \"^4.1.0\",\n    \"yaml\": \"^2.9.1\"\n  },\n  \"scripts\": {\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"vitest run\",\n    \"test:controller\": \"python3 -B tests/dsh-cognition-contract.test.py\",\n    \"test:integrity\": \"python3 -B preset/skills/j-space/scripts/verify_suite.py && python3 -B tools/upstream_integrity.py verify --runtime preset/skills/j-space --adapters vendor/j-space/adapters.json\",\n    \"test:lossless\": \"python3 -B tests/upstream-integrity.test.py\",\n    \"test:upstream\": \"python3 -B tests/run-upstream-tests.py\",\n    \"test:host\": \"node tests/dsh-host-compat.mjs\",\n    \"test:install\": \"node tests/dsh-install-smoke.mjs\",\n    \"status\": \"node bin/cli.js status\",\n    \"install:preset\": \"node bin/cli.js install\",\n    \"uninstall:preset\": \"node bin/cli.js uninstall\",\n    \"verify\": \"node bin/cli.js verify\"\n  }\n}\n"
