      "path": "cordis.patch.yml",
      "content": "# @anonyjcy/dsh-j-space — DSH 0.2.1 preset bundle patch (validated on 0.2.1-alpha.3).\n#\n# A preset is a declaration row carried by a bundle patch. Since DSH 0.1.7 nothing\n# reads `$DSH_HOME/.agent-presets/`, so the previous shape of this file — a row\n# that merely mounted the deployer plugin — no longer registers any preset.\n#\n# This bundle therefore declares `j-space` directly, the way the shipped presets\n# (`@deepseek-ai/dsh-web-app/presets/*.patch.yml`) do: one\n# `@deepseek-ai/dsh-agent-preset` row whose `config.plugins` is the preset's own\n# composition. The composition is the same agent-plane composition as\n# `preset/agent.cordis.yml`; it is inlined here because a preset row is the\n# contract and a bundle cannot point at a sibling file.\n#\n# The Loader row id is `preset-<config.id>` by convention, so `preset-j-space`\n# declares the preset id `j-space` that sessions record in their header.\n#\n# Native profile loading evaluates `!!js` with the profile's `baseUrl`, not\n# this bundle's original directory. Resolve this installed package's exported\n# package.json from that profile, then locate its own `preset/skills/` tree.\n#\n# `!!js` is evaluated by the Loader, so the shell rows stay platform-conditional\n# (`tool-bash` on POSIX, `tool-pwsh` on Windows).\n#\n# `src/` and the `dsh-j-space` CLI remain available for the legacy\n# `$DSH_HOME/.agent-presets/` deployment; they are no longer how the preset is\n# registered.\n\n\n- insert:\n    - id: preset-j-space\n      name: '@deepseek-ai/dsh-agent-preset'\n      config:\n        id: j-space\n        name: J-Space Cognition Suite\n        description: J-Space Cognition Suite SV1 认知工作空间 Agent，具备深层推理路由、持久控制器（control.py）、状态外化账本与自适应验证能力。\n        order: 5\n        plugins:\n          # The `j-space` agent preset: J-Space Cognition Suite SV1 coding agent.\n          #\n          # This file is an AGENT-PLANE composition. The roster mounts it ONCE under a\n          # standing scope; every session naming it joins by scope parentage, so the\n          # tools, prompt sections, and J-Space skills registered here cover each joined\n          # agent while a session's own state stays keyed per Session/Agent inside the\n          # plugins. The host composition keeps everything a preset must not own: the\n          # registries themselves, the sandbox and approval stack, persistence, and the\n          # model route.\n          #\n          # A service row here MUST sit inside a group carrying an `isolate` realm.\n\n          # ── identity ────────────────────────────────────────────────────────────────\n\n          # The preset's own persona, shadowing the deployment default for this agent.\n          # `{{model}}` and `{{cwd}}` resolve from the agent's own route and workspace.\n          - id: persona\n            name: '@deepseek-ai/dsh-persona'\n            config:\n              suffix: Your working directory is {{cwd}}.\n              prefix: >-\n                You are a coding agent powered by the {{model}} model, operating with the J-Space Cognition Suite SV1 architecture.\n\n          - id: agent-instructions\n            name: '@deepseek-ai/dsh-agent-instructions'\n            config:\n              maxBytes: 65536\n\n          # Time context follows the DSH 0.2.1 standard preset.\n          - id: time-context\n            name: '@deepseek-ai/dsh-time-context'\n\n          # ── shell ───────────────────────────────────────────────────────────────────\n\n          - id: tool-bash\n            name: '@deepseek-ai/dsh-tool-bash'\n            disabled: !!js process.platform === 'win32'\n\n          - id: tool-pwsh\n            name: '@deepseek-ai/dsh-tool-pwsh'\n            disabled: !!js process.platform !== 'win32'\n\n          # ── filesystem ──────────────────────────────────────────────────────────────\n\n          - id: tool-fs\n            name: '@deepseek-ai/dsh-tool-fs'\n\n          - id: tool-fs-search\n            name: '@deepseek-ai/dsh-tool-fs-search'\n            config:\n              sampleOverCapGlobResults: false\n\n          # ── background jobs ────────────────────────────────────────────────────────\n\n          - id: tool-jobs\n            name: '@deepseek-ai/dsh-tool-jobs'\n\n          - id: tool-schedule\n            name: '@deepseek-ai/dsh-tool-schedule'\n\n          # ── skills ──────────────────────────────────────────────────────────────────\n\n          # Skills remain inside this installed package, not under the profile root.\n          # Resolve exported package metadata from the profile before locating them.\n          # Both rows register into THIS preset's layer of the host skill registry.\n          - id: skill-filesystem\n            name: '@deepseek-ai/dsh-skill-filesystem'\n            config:\n              customSkillDirs:\n                - !!js \"process.getBuiltinModule('node:path').join(process.getBuiltinModule('node:path').dirname(process.getBuiltinModule('node:module').createRequire(new URL('package.json', baseUrl)).resolve('@anonyjcy/dsh-j-space/package.json')), 'preset/skills')\"\n\n          - id: tool-skill\n            name: '@deepseek-ai/dsh-tool-skill'\n\n          # ── goals ───────────────────────────────────────────────────────────────────\n\n          - id: command-goal\n            name: '@deepseek-ai/dsh-command-goal'\n\n          - id: tool-goal\n            name: '@deepseek-ai/dsh-tool-goal'\n\n          # ── plan mode ───────────────────────────────────────────────────────────────\n\n          - id: planning\n            name: cordis:group\n            group: true\n            isolate:\n              planMode: true\n            config:\n              - id: plan-mode\n                name: '@deepseek-ai/dsh-plan-mode'\n                config:\n                  section: |\n                        You are in plan mode. Stay in plan mode until the user approves your plan through exit_plan_mode or switches the session mode. Imperative language to implement changes means plan the implementation, not execute it. A user's conversational agreement — including an answer confirming something you asked — approves nothing and does not end plan mode; fold the confirmed decision into the plan and submit it through exit_plan_mode.\n\n                        Explore first. Use non-mutating reads, searches, static analysis, and checks to ground the plan in the actual repository. Do not edit or write files, change configuration, run formatters or code generation that rewrites tracked files, commit, or otherwise carry out the plan. Prefer existing functions and patterns over new machinery.\n\n                        The tool catalog stays the same across modes for request-cache stability. These plan-mode rules override any later tool description or guidance that suggests using mutation tools; those tools remain listed to keep the tool catalog unchanged. Do not use todo_write to track this planning phase: it tracks implementation after an approved plan, while the plan itself belongs in exit_plan_mode.\n\n                        Resolve discoverable facts by inspection. Use ask_user_question only for user-owned choices or material ambiguity that inspection cannot answer. Do not ask the user where code lives or how current behavior works when you can find out.\n\n                        Make the plan decision-complete: state the goal and success criteria; group implementation changes by subsystem; identify public API, schema, and data-flow changes; cover edge cases, failure modes, tests, acceptance criteria, and explicit assumptions. Keep it concise enough to review but detailed enough that another engineer can implement it without making design decisions.\n\n                        When ready, call exit_plan_mode with the complete plan markdown, starting with a # title. Make exit_plan_mode the only and final tool call in that assistant response: it presents the plan for approval, and implementation begins only in a later step after approval. Do not paste the final plan as a plain reply or ask \"should I proceed?\" through prose or ask_user_question. If review rejects it, incorporate the feedback and present again. If the review channel is unavailable or aborted, stay in plan mode and ask the user to switch modes manually; do not proceed with implementation.\n\n          # ── compaction ──────────────────────────────────────────────────────────────\n\n          - id: compaction\n            name: cordis:group\n            group: true\n            isolate:\n              compaction: true\n              toolResultPruner: true\n            config:\n              - id: compaction-basic\n                name: '@deepseek-ai/dsh-compaction-basic'\n\n              - id: command-compact\n                name: '@deepseek-ai/dsh-command-compact'\n\n              - id: tool-result-pruner\n                name: '@deepseek-ai/dsh-compaction-tool-result-pruner'\n                config:\n                  thresholdChars: 8192\n                  headChars: 4096\n                  tailChars: 1024\n\n          # ── official batch workflows ────────────────────────────────────────────────\n          # Direct delegation, team membership and coordination belong to the official\n          # DSH Agent Teams host plugin. Do not mount preset-local subagent/control rows:\n          # host profile patches do not traverse a preset's config.plugins composition.\n          # Keep the official workflow engine for explicitly requested batch workflows;\n          # workflow children are not Team members and must not be used as a Team fallback.\n\n          - id: delegation\n            name: cordis:group\n            group: true\n            isolate:\n              workflowEngine: true\n            config:\n              - id: workflow-ptc\n                name: '@deepseek-ai/dsh-workflow-ptc'\n                config:\n                  provider: spawn\n\n              - id: tool-workflow\n                name: '@deepseek-ai/dsh-tool-workflow'\n\n          # ── remaining model-facing rows ─────────────────────────────────────────────\n\n          - id: tool-ask-user\n            name: '@deepseek-ai/dsh-tool-ask-user'\n\n          - id: tool-todo\n            name: '@deepseek-ai/dsh-tool-todo'\n            config:\n              allowParallelInProgress: true\n\n          - id: present\n            name: '@deepseek-ai/dsh-tool-present'\n\n          - id: tool-plugin-manager\n            name: '@deepseek-ai/dsh-plugin-manager/tools'\n            disabled: true\n\n          - id: tool-web\n            name: '@deepseek-ai/dsh-tool-web'\n            config:\n              fetch: true\n              searchTimeoutMs: 60000\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * Standalone plugin for DeepSeek Harness that integrates J-Space Cognition Suite SV1 as an Agent Preset.\n * @module @anonyjcy/dsh-j-space\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { installJSpacePreset, isJSpacePresetInstalled } from './installer.ts'\n\nexport {\n  getJSpaceTemplatePath,\n  installJSpacePreset,\n  isJSpacePresetInstalled,\n  PRESET_ID,\n  targetUserPresetDir,\n  uninstallJSpacePreset,\n  USER_PRESET_DIR,\n  verifyJSpacePreset,\n  type InstallOptions,\n  type VerificationResult,\n} from './installer.ts'\n\n/** Cordis plugin name. */\nexport const name = 'plugin-j-space'\n\n/** Configuration options for the plugin. */\nexport interface Config {\n  /** Auto-deploy preset to user preset directory if missing (default: true). */\n  autoDeploy?: boolean\n}\n\n/**\n * Apply the J-Space plugin to a Cordis Context.\n * Deploys the legacy preset files if missing; DSH 0.2.1 registration is\n * handled separately by the package's bundle patch.\n * @param ctx - Cordis context.\n * @param config - plugin configuration.\n */\nexport async function apply(ctx: Context, config: Config = {}): Promise<void> {\n  const autoDeploy = config.autoDeploy ?? true\n  if (!autoDeploy) return\n\n  // Cordis awaits async plugin application, including mounts in an active host.\n  // It does not emit the old `ready` event in Cordis 4.\n  try {\n    const installed = await isJSpacePresetInstalled()\n    if (!installed) {\n      await installJSpacePreset()\n      ctx.logger.info('J-Space Cognition Suite SV1 preset deployed to DSH user presets directory.')\n    }\n  } catch (error) {\n    ctx.logger.warn(`Failed to auto-deploy J-Space preset: ${String(error)}`)\n  }\n}\n\nexport default {\n  name,\n  apply,\n}\n"
    },
